#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
    BOLD=$(tput bold)
    DIM=$(tput dim)
    RESET=$(tput sgr0)
    BLUE=$(tput setaf 4)
    GREEN=$(tput setaf 2)
    YELLOW=$(tput setaf 3)
else
    BOLD=""
    DIM=""
    RESET=""
    BLUE=""
    GREEN=""
    YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
    [[ -t 1 ]] || return 0
    if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
    printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
    _clear
    printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
    printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
    printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
    printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
    printf '  later, since it remembers values already saved.%s\n' "$RESET"
    pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
    _clear
    _STAGE_INDEX=$((_STAGE_INDEX + 1))
    printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
        "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say() { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
    local url="$1"
    printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
    {
        if command -v wslview >/dev/null 2>&1; then
            wslview "$url"
        elif command -v explorer.exe >/dev/null 2>&1; then
            explorer.exe "$url"
        elif command -v xdg-open >/dev/null 2>&1; then
            xdg-open "$url"
        elif command -v open >/dev/null 2>&1; then
            open "$url"
        else false; fi
    } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
    printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
    read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
    local reply=""
    printf '  %s? %s [y/N] ' "$YELLOW" "$1"
    read -r reply || true
    [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
    [[ -f "$ENV_FILE" ]] || return 1
    local line value sq="'\\''"
    line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
    value="${line#*=}"
    if [[ "$value" == \'*\' ]]; then
        value="${value:1:${#value}-2}"
        value="${value//"$sq"/\'}"
    elif [[ "$value" == \"*\" ]]; then
        value="${value:1:${#value}-2}"
        [[ "$value" == *[\\\$\"]* ]] && return 1 # escapes, $ or ": can't decode safely; ask again
    fi
    printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
    local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
    current=$(_existing "$key" || true)
    # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
    p="  $s$BOLD$e$prompt$s$RESET$e "
    [[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps current]$s$RESET$e "
    read -e -r -p "$p" input || rc=1
    if ((rc)) && [[ -z "$input" ]]; then return 1; fi
    [[ -z "$input" && -n "$current" ]] && input="$current"
    printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
    local key="$1" value="$2" tmp sq="'\\''"
    [[ -e "$ENV_FILE" ]] || (umask 077 && : >"$ENV_FILE")
    tmp=$(mktemp)
    grep -vE "^${key}=" "$ENV_FILE" >"$tmp" || true
    printf "%s='%s'\n" "$key" "${value//\'/$sq}" >>"$tmp"
    cat "$tmp" >"$ENV_FILE"
    rm -f "$tmp"
    printf -v "$key" '%s' "$value"
    WRITTEN_ENV+=("$key")
    printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
    _clear
    printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
    ((${#WRITTEN_ENV[@]})) && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
    ((${#WRITTEN_SECRET[@]})) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
    if ((${#SKIPPED[@]})); then
        printf '\n'
        warn "still to do by hand:"
        for s in "${SKIPPED[@]}"; do note "  - $s"; done
    fi
    printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

    TOTAL_STAGES=5

    REPO=ltowarek/dust-mite

    local tool
    for tool in gh jq curl openssl; do
        command -v "$tool" >/dev/null 2>&1 || {
            warn "this wizard needs $tool on the host"
            exit 1
        }
    done
    cd "$(git rev-parse --show-toplevel)"
    MAIN_CHECKOUT=$(dirname "$(git rev-parse --path-format=absolute --git-common-dir)")
    AFK_APP_SLUG=$(gh variable get AFK_APP_SLUG --repo "$REPO" 2>/dev/null || true)
    AFK_APP_CLIENT_ID=$(gh variable get AFK_APP_CLIENT_ID --repo "$REPO" 2>/dev/null || true)

    banner "AFK GitHub App: car agent session key"

    stage "Add the Checks permission"
    if [[ -z "$AFK_APP_SLUG" ]]; then
        warn "couldn't read the AFK_APP_SLUG Actions variable."
        ask AFK_APP_SLUG "Paste the App's slug:"
    fi
    say "Car agent sessions report DUT runs as check runs, so the App needs Checks write."
    open_url "https://github.com/settings/apps/$AFK_APP_SLUG/permissions"
    step "Under 'Repository permissions', set 'Checks' to 'Read and write'."
    step "Check that 'Workflows' is still 'No access'."
    step "Click 'Save changes' at the bottom, and confirm if GitHub asks."
    pause "Press Enter once the change is saved."

    stage "Accept the new permission"
    say "The installation keeps the old permissions until you accept the request."
    open_url "https://github.com/settings/installations"
    step "Click 'Configure' next to $AFK_APP_SLUG."
    step "In the banner about updated permissions, click 'Review request'."
    step "Click 'Accept new permissions'."
    pause "Press Enter once the installation shows the new permission."

    stage "Generate the second private key"
    say "This key is for car agent sessions only; AFK runs keep the first key."
    open_url "https://github.com/settings/apps/$AFK_APP_SLUG"
    step "Scroll to 'Private keys' and click 'Generate a private key'."
    step "Your browser downloads a .pem file."
    ask DOWNLOADED_KEY "Path to the downloaded .pem:"
    DOWNLOADED_KEY="${DOWNLOADED_KEY/#\~/$HOME}"
    while [[ ! -f "$DOWNLOADED_KEY" ]]; do
        warn "no file at $DOWNLOADED_KEY"
        ask DOWNLOADED_KEY "Path to the downloaded .pem:"
        DOWNLOADED_KEY="${DOWNLOADED_KEY/#\~/$HOME}"
    done
    pause

    stage "Move the key outside the repo"
    say "The key moves to a private file on this PC; no copy stays in Downloads."
    say "The desk script reads its path from AFK_APP_KEY_FILE in $ENV_FILE."
    note "for example: ~/.config/dust-mite/afk-app-car.pem"
    while true; do
        ask AFK_APP_KEY_FILE "Absolute path for the key:"
        AFK_APP_KEY_FILE="${AFK_APP_KEY_FILE/#\~/$HOME}"
        if [[ "$AFK_APP_KEY_FILE" != /* ]]; then
            warn "use an absolute path or one starting with ~"
            continue
        fi
        if _in_repo "$AFK_APP_KEY_FILE"; then
            warn "$AFK_APP_KEY_FILE is inside the repo; pick a path outside $MAIN_CHECKOUT"
            continue
        fi
        if [[ -e "$AFK_APP_KEY_FILE" ]] && ! confirm "Overwrite the existing $AFK_APP_KEY_FILE?"; then
            continue
        fi
        (umask 077 && mkdir -p "$(dirname "$AFK_APP_KEY_FILE")")
        AFK_APP_KEY_FILE="$(cd "$(dirname "$AFK_APP_KEY_FILE")" && pwd -P)/$(basename "$AFK_APP_KEY_FILE")"
        if _in_repo "$AFK_APP_KEY_FILE"; then
            warn "$AFK_APP_KEY_FILE resolves inside the repo; pick another path"
            continue
        fi
        break
    done
    mv -f -- "$DOWNLOADED_KEY" "$AFK_APP_KEY_FILE"
    chmod 600 "$AFK_APP_KEY_FILE"
    note "moved the key to $AFK_APP_KEY_FILE (mode 0600)"
    write_env AFK_APP_KEY_FILE "$AFK_APP_KEY_FILE"
    pause

    stage "Verify the key and permissions"
    say "Signs in as the App with the new key and reads the installation's permissions."
    if [[ -z "$AFK_APP_CLIENT_ID" ]]; then
        warn "couldn't read the AFK_APP_CLIENT_ID Actions variable."
        ask AFK_APP_CLIENT_ID "Paste the App's Client ID:"
    fi
    local permissions
    if permissions=$(_installation_permissions "$AFK_APP_CLIENT_ID" "$AFK_APP_KEY_FILE"); then
        printf '%s\n' "$permissions" | jq -r 'to_entries[] | "    \(.key): \(.value)"'
        if jq -e '.checks == "write" and (has("workflows") | not)' <<<"$permissions" >/dev/null; then
            note "Checks write is granted and Workflows is absent."
        else
            warn "the permissions don't match: expected Checks write and no Workflows."
            SKIPPED+=("fix the App's permissions at https://github.com/settings/apps/$AFK_APP_SLUG/permissions, then accept them on the installation")
        fi
    else
        warn "couldn't read the installation with the new key."
        SKIPPED+=("check that $AFK_APP_KEY_FILE belongs to $AFK_APP_SLUG and that the App is installed on $REPO")
    fi
    pause

    finish
}

# _in_repo PATH succeeds when PATH is inside this checkout or the main checkout.
_in_repo() {
    local root
    for root in "$PWD" "$MAIN_CHECKOUT"; do
        [[ "$1" == "$root" || "$1" == "$root"/* ]] && return 0
    done
    return 1
}

_b64url() { openssl base64 -A | tr '+/' '-_' | tr -d '='; }

# _installation_permissions CLIENT_ID KEY_FILE prints the installation's permissions as JSON.
_installation_permissions() {
    local now header payload signature
    now=$(date +%s)
    header=$(printf '{"alg":"RS256","typ":"JWT"}' | _b64url)
    payload=$(printf '{"iat":%d,"exp":%d,"iss":"%s"}' $((now - 60)) $((now + 540)) "$1" | _b64url)
    signature=$(printf '%s.%s' "$header" "$payload" | openssl dgst -sha256 -sign "$2" -binary | _b64url) || return 1
    curl -fsS \
        -H "Authorization: Bearer $header.$payload.$signature" \
        -H "Accept: application/vnd.github+json" \
        "https://api.github.com/repos/$REPO/installation" | jq -e '.permissions'
}

run_wizard "$@"
exit
